--- 设置boss面板的canvas层级（角色详情的时候，要把boss面板层级提高，让他出现在角色详情的上面）
---@param order number 层级 (-1:默认)
function UIBattlingBossInfoPanel:SetBossPanelCanvasOrder(order)
    if order == -1 then
        self.Canvas_root.overrideSorting = false
    else
        self.Canvas_root.overrideSorting = true
        self.Canvas_root.sortingOrder = order
    end
end

--- 抬高bossInfo的层级，超过UIBattlingDialog里面的rootDrag，保证可以被点击到
function UIBattlingBossInfoPanel:SetBossInfoCanBeClicked(state)
    if isNull(self.roleId) then
        return
    end
    if state then
        self.cgBossPanel.blocksRaycasts = true
        self:SetBossPanelCanvasOrder(10)
        KTool.SetActive(self.BtnShowBuff, true)
    else
        self.cgBossPanel.blocksRaycasts = false
        self:SetBossPanelCanvasOrder(0)
        KTool.SetActive(self.BtnShowBuff, false)
    end
end

---SetBossInfoPanel
---设置 BossInfoPanel 信息
---@param data table @ {bossId, bossLv, bossAttri, bossHp, bossSp, spMax}
function UIBattlingBossInfoPanel:SetBossInfoPanel(data)
    xTry(function()
        local characterSkinId = UIBattlingDataMgr:GetCharacterSkinIdById(BattleInfo.otherCamp, data.bossId)
        local bossData = UIBattlingTools.GetCardSkinDataBySkinId(characterSkinId)
        local bossHeadPath = bossData.battleBossHead
        local bossAttributeType = data.bossAttri
        local bossHpInStart = data.bossHp
        local bossSpInStart = data.bossSp
        self.roleId = data.bossId
        self.numSpMax = data.SpMax
        
        if not isNull(data.multiNum) and data.multiNum > 1 then
            self.isMultiMode = true
            self.multiNum = data.multiNum
            KTool.SetActive(self.Txt_MultiNum, true)
            self.Txt_MultiNum.text = string.format("x%d", self.multiNum)

            -- 设置第一条血的颜色
            KTool.SetActive(self.RT_HpSliderMultilayer, true)
            self.LT_hpTopSlider:SetColor(Constants.HPMultiSliderColor[0])
            self:SetNextHPSliderColor(Constants.HPMultiSliderColor[1])
        end
        self:SetBossHp(bossHpInStart)
        self:InitSpRoot()
        self:UpdateBossSpNode(bossSpInStart)
        self:SetBossAttribute(bossAttributeType)
        self.BossIconImg:LoadSprite(bossHeadPath)
        self.BossIconImg2:LoadSprite(bossHeadPath)
        self.BossIconImg3:LoadSprite(bossHeadPath)
        self:SetBossPanelShowState(true)
        self:BossAnimatorPlay(BOSS_ANIMATIONS.Enter)
        KTool.SetActive(self.BossBuffRoot.gameObject, true)
    end)
end

function UIBattlingBossInfoPanel:SetBossAttribute(type)
    if self.Img_Attribute then
        local attriTypeIconPath = CardUtils.GetCardAttrIconPath(type)
        if attriTypeIconPath then
            self.Img_Attribute:LoadSprite(attriTypeIconPath)
        end
    end
end

---SetBossHp
--- 设置 Boss HP
---@param hpPre number @ 百分比
function UIBattlingBossInfoPanel:SetBossHp(hpPre)
    --self.BossHpImg.fillAmount = hpPre <= 0 and 0 or hpPre
    local value = hpPre <= 0 and 0 or hpPre
    value = hpPre >= 1 and 1 or hpPre
    self:BossHpChange(value)
    self.hpCurrentProgress = value
    if value > 0 and value <= 0.001 then
        value = 0.001
    end
    local progress = checkNumber(value * 1000 / 10)
    local _string = string.format("%0.1f", progress)
    self.Txt_HpNum.text = string.format("%s%%", _string)
    KTool.SetActive(self.DeadNode.gameObject ,value <= 0)
    --- Boss 死亡
    if value <= 0 then
        self:BossAnimatorPlay(BOSS_ANIMATIONS.Die)
        KTool.SetActive(self.BossBuffRoot.gameObject, false) -- 清理 buff 列表
        self:CleanBossWeakFX() -- 清理 boss 解体特效
        -- self:SetBossHPLight(false)
        --- 设置元素解体状态显示状态
        local battlingCtrMgr = import("Game.UI.UIBattling.UIBattlingCtrlMgr")
        local refEleBreakPanel = battlingCtrMgr:GetInstance():GetEleBreakLuaTable()
        if refEleBreakPanel then
            refEleBreakPanel:SetPanelRootState(false)
        end
    end
end

---BossHpChange
---Boss 血量变化 动效
---@param preNow number @ 百分比
function UIBattlingBossInfoPanel:BossHpChange(preNow)
    local oldProgress = self.hpCurrentProgress
    local newProgress = preNow

    if self.isMultiMode then
        -- 多条模式
        local oldShowNum, oldShowProgress = UIBattlingTools.HP2MultiMode(oldProgress, self.multiNum)
        local newShowNum, newShowProgress = UIBattlingTools.HP2MultiMode(newProgress, self.multiNum)

        if newProgress > oldProgress  then
            -- 加血
            -- 设置数量
            self.LT_hpMidSlider:SetProgress(newShowProgress)
            self.LT_hpTopSlider:SetProgress(newShowProgress)
            -- self:SetHpEndPoint()
        else
            -- 扣血
            if oldShowNum == newShowNum then
                self.LT_hpTopSlider:SetProgress(newShowProgress)
                self.LT_hpMidSlider:DelayLerpProgress2(newShowProgress, 1, 0.12)
            else
                self.LT_hpTopSlider:SetProgress(newShowProgress)
                if newShowNum > 0 then
                    self.LT_hpMidSlider:SetProgress(1)  -- 把条重置到满的，并停掉之前的lerp。最后一管血的时候就不用重置到满了
                end
                self.LT_hpMidSlider:DelayLerpProgress2(newShowProgress, 1, 0.12)
                
                -- 掉光一条血时，播放动画
                local dialog = UIBattlingCtrlMgr:GetInstance():GetBattlingInfoDialog()
                if dialog then
                    local anim = dialog.AnimatorRoot
                    if anim then
                        anim:CrossFadeInFixedTime("CharactorI_State_Shake", 0)
                    end
                end

                -- 切换血条的颜色
                if newShowNum == 1 then
                    -- 最后一条
                    self.LT_hpTopSlider:SetColor(Constants.HPMultiSliderColor[-1])
                else
                    local colorIndex = (self.multiNum - newShowNum) % 4
                    self.LT_hpTopSlider:SetColor(Constants.HPMultiSliderColor[colorIndex])
                    self:SetNextHPSliderColor(Constants.HPMultiSliderColor[colorIndex + 1])
                end
            end
        end
        -- 设置条数
        self.Txt_MultiNum.text = string.format("x%d", newShowNum)
        KTool.SetActive(self.Txt_MultiNum, newShowNum > 1)  -- 最后一条血不显示数字了
        KTool.SetActive(self.RT_HpSliderMultilayer, newShowNum > 1)  -- 除了最后一条血，都显示下一条血的颜色
    else
        -- 单条模式
        if newProgress > oldProgress  then
            -- 加血
            self.LT_hpMidSlider:SetProgress(newProgress)
            self.LT_hpTopSlider:SetProgress(newProgress)
        else
            -- 扣血
            self.LT_hpTopSlider:SetProgress(newProgress)
            self.LT_hpMidSlider:DelayLerpProgress2(newProgress, 1, 0.12)
        end
    end
    

    -- 根据血线修改血条颜色
    -- if newProgress > 0.7 then
    --     self.LT_hpTopSlider:SetColor(Constants.HPSliderColor.Green)
    -- elseif newProgress > 0.4 then
    --     self.LT_hpTopSlider:SetColor(Constants.HPSliderColor.Yellow)
    -- else
    --     self.LT_hpTopSlider:SetColor(Constants.HPSliderColor.Red)
    -- end
end

