-- dialog.Env.bossInfoPanelLB.Env:TestDoDelayLerp(0.01, 0.2, 1, 0.2)
-- --dialog.Env.bossInfoPanelLB.Env:TestResetDoDelayLerp()
function UIBattlingBossInfoPanel:TestDoDelayLerp(damage, interval, delay, duration)
    local toP = 1
    -- local damage = 0.01      -- 伤害
    -- local interval = 0.2     -- 伤害频率
    -- local delay = 1          -- 控制mid条的长度
    -- local duration = 0.12    -- 控制mid条的插值平滑度（duration建议小于interval，否则可能一直追不上top条）
    self.testCo = cs_coroutine.start(function()
        while toP > 0 do
            toP = toP - damage
            self.LT_hpTopSlider:SetProgress(toP)
            self.LT_hpMidSlider:DelayLerpProgress(toP, delay, duration)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(interval))
        end
        self.testCo = nil
    end)
end

function UIBattlingBossInfoPanel:TestResetDoDelayLerp()
    if not isNull(self.testCo) then
        cs_coroutine.stop(self.testCo)
    end
    self.LT_hpTopSlider:SetProgress(1)
    self.LT_hpMidSlider:SetProgress(1)
    self.LT_hpMidSlider:StopCo()
end

---SetBossSp
---设置 Boss BossSP
---@param data table
function UIBattlingBossInfoPanel:SetBossSp(data)
    local spPoint = checkNumber(data.bossSP)
    if spPoint > self.numSpMax then
        spPoint = self.numSpMax
    elseif spPoint <= 0 then
        spPoint = 0
    end
    self:UpdateBossSpNode(spPoint)
end

--- boss护盾罩子动画
---@param value any
---@param valueMax any
function UIBattlingBossInfoPanel:ShieldShellAnimation(value, valueMax)
    local oldProgress = self.curShieldProgress
    local newProgress = value / valueMax
    if newProgress > 0 then
        if oldProgress <= 0 then
            -- 加盾动画
            -- print("[护盾] 加盾")
            self.CG_ShieldCover.alpha = 1
            self.Animation_ShieldCover:Play(AnimationShowShield)
        else
            -- 受击动画
            -- print("[护盾] 受击")
            KTool.SetActive(self.RT_FXShieldGlow, false)
            local oldEndPoint = self.LT_shieldSlider:CalculateEndPoint(oldProgress)
            local newEndPoint = self.LT_shieldSlider:CalculateEndPoint(newProgress)
            self.RT_FXShieldGlow.sizeDelta = Vector2.New(oldEndPoint.x, self.RT_FXShieldGlow.sizeDelta.y)
            self.RT_FXShieldHit.localPosition = Vector3.New(newEndPoint.x, newEndPoint.y, 0)
            KTool.SetActive(self.RT_FXShieldGlow, true)
        end
    else
        if valueMax > 0 then
            -- 碎盾动画
            -- print("[护盾] 碎盾")
            self.Animation_ShieldCover:Play(AnimationBreakShield)
        else
            -- 消失动画
            -- print("[护盾] 消失")
            self.CG_ShieldCover:DOFade(0, 0.3)
        end
    end
end

---SetBossShield
---设置 Boss Shield
---@param valuePre number
function UIBattlingBossInfoPanel:SetBossShield(data)
    if isNull(self.shieldValueEX) then self.shieldValueEX = 0 end
    self:ShieldShellAnimation(data.shieldValue, data.shieldValueMax)    -- 护盾罩子动画
    local shieldValue = data.shieldValue
    local shieldValueMax = data.shieldValueMax
    local shieldPre = shieldValue / shieldValueMax
    self.curShieldProgress = shieldPre
    shieldPre = math.floor(shieldPre * 100 + 0.5) * 0.01
    if shieldPre <= 0 then
        shieldPre = 0
    elseif shieldPre >= 1 then
        shieldPre = 1
    end
    self.BossShieldRoot.alpha = shieldPre > 0 and 1 or 0
    if shieldPre <= 0 then return shieldPre end
    if self.coShowShieldChange then
        cs_coroutine.stop(self.coShowShieldChange)
        self.coShowShieldChange = nil
    end

    self.LT_shieldSlider:LerpProgress(shieldPre, 0.12, self.shieldLerpCurve)

    -- self.coShowShieldChange = cs_coroutine.start(function()
    --     local PreChange = self.BossShieldImg.localScale.x - shieldPre
    --     local timeProcess = 0
    --     while timeProcess <= Constants.TIME_HP_CHANGE do
    --         timeProcess = timeProcess + Time.deltaTime
    --         local timePre = Time.deltaTime / Constants.TIME_HP_CHANGE
    --         local valueX = self.BossShieldImg.localScale.x - timePre * PreChange
    --         self.BossShieldImg.localScale = Vector3.New(valueX, self.BossShieldImg.localScale.y, self.BossShieldImg.localScale.z)
    --         cs_coroutine.yield_return()
    --     end
    --     self.coShowShieldChange = nil
    -- end)
    
    self.shieldValueEX = shieldPre
    return shieldPre
end

function UIBattlingBossInfoPanel:InitSpRoot()
    if self.listSPNodes then
        for i = #self.listSPNodes, 1, -1 do
            if not isNull(self.listSPNodes[i].gameObject) then
                KTool.SafeDelete(self.listSPNodes[i].gameObject)
            end
        end
        self.listSPNodes = nil
    end
    self.listSPNodes = {}
    if not IsNull(self.BossSpRoot) and not IsNull(self.Img_SpPoint) then
        for i = 1, self.numSpMax do
            local spNode = KTool.Instantiate(self.BossSpRoot.gameObject, self.Img_SpPoint.gameObject)
            KTool.SetActive(spNode,true)
            local switchImg1
            local Img1 = spNode.transform:Find("Img1")
            if not IsNull(Img1) then
                switchImg1 = KTool.GetComponent(Img1.gameObject, typeof(UISwitchImage))
            end
            local goImg2 = spNode.transform:Find("Img2")
            local tableSPNode = { Img1 = switchImg1, Img2 = goImg2, gameObject = spNode  }
            table.insert(self.listSPNodes, tableSPNode)
        end
    end
end

