---SetBossWeaknessFX
---设置 Boss 虚弱FX
function UIBattlingBossInfoPanel:SetBossWeaknessFX(data)
    local bossState = data.state
    if IsNull(bossState) then return end
    if bossState == PanelShowState.Sleep then
        self:RecycleWeakBreakFX()
        self:RecycleWeakBrokenFX()
        -- self:SetBossHPLight(false)
        self.UISwitchImg_BossHeadBgLine.Status = 1
    elseif bossState == PanelShowState.Running then
        UIBattlingTools.PlayAudio(UISheets.UI_Battle.ui_battle_enemy_01)
        self:SetBossWeakBreaking()
        self.UISwitchImg_BossHeadBgLine.Status = 1
    elseif bossState == PanelShowState.Weakness then
        UIBattlingTools.PlayAudio(UISheets.UI_Battle.ui_battle_enemy_02)
        self:SetBossWeakBroken()
        self.UISwitchImg_BossHeadBgLine.Status = 2
    elseif bossState == PanelShowState.Out then
        self:CleanBossWeakFX()
        -- self:SetBossHPLight(false)
        self.UISwitchImg_BossHeadBgLine.Status = 1
    end
end

function UIBattlingBossInfoPanel:BossAnimatorPlay(name)
    if not IsNull(self.AnimatorBoss) then
        self.AnimatorBoss:Play(name,0,0)
        self.AnimatorBoss:Update(0)
    end
end

