---SetBossWeakBreaking
---展示 boss 弱点击破开始
function UIBattlingBossInfoPanel:SetBossWeakBreaking()
    self:BossAnimatorPlay(BOSS_ANIMATIONS.StateBreakStar)
    -- self:SetBossHPLight(true, 1)
    self.coShowWeakEnter = cs_coroutine.start(function()
        --self.ptcBossWeakBreakingEnter = UIBattlingTools.ReloadPTCOfBattling(Constants.UIBattlingObjPoolPTC.PTC_BREAKING_ENTER, self.Root_BossHead.gameObject, 9999,true)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.3))
        self.ptcBossWeakBreakingDuration = UIBattlingTools.ReloadPTCOfBattling(Constants.UIBattlingObjPoolPTC.PTC_BREAKING_DURATION, self.Root_BossHead.gameObject, 9999, true)
    end)
end

---SetBossWeakBroken
---展示 boss 弱点击破完成
function UIBattlingBossInfoPanel:SetBossWeakBroken()
    self:RecycleWeakBreakFX()
    -- self:SetBossHPLight(true, 2)
    self.coShowBroken = cs_coroutine.start(function()
        self:BossAnimatorPlay(BOSS_ANIMATIONS.StateBreaking)
        --self.ptcBossWeakBrokenEnter = UIBattlingTools.ReloadPTCOfBattling(Constants.UIBattlingObjPoolPTC.PTC_BROKEN_ENTER, self.Root_BossHead.gameObject, 9999, true)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.1))
        --self:BossAnimatorPlay(BOSS_ANIMATIONS.StateBreaking)
        self.ptcBossWeakBrokenDuration = UIBattlingTools.ReloadPTCOfBattling(Constants.UIBattlingObjPoolPTC.PTC_BROKEN_DURATION, self.Root_BossHead.gameObject, 9999, true)
    end)
end

--todo 解体状态下监听伤害跳字消息，当前角色首攻击后，播特效， 重新进入休眠 取消监听
function UIBattlingBossInfoPanel:InitWeakBrokenHitEvent()
    self:RemoveWeakBrokenHitEvent()
    self.eventShowDamage = Events.AddListener(Constants.EventNames.BattleDamageShow, function(data)
        local roleId = data.roleId
        if roleId == self.roleId then
            UIBattlingTools.ReloadPTCOfBattling(Constants.UIBattlingObjPoolPTC.PTC_ELEMENT_NODE_BREAK, self.Root_BossHead.gameObject, 1, true)
        end
    end)
end

function UIBattlingBossInfoPanel:RemoveWeakBrokenHitEvent()
    if self.eventShowDamage then
        Events.RemoveListener(Constants.EventNames.BattleDamageShow, self.eventShowDamage)
        self.eventShowDamage = nil
    end
end

function UIBattlingBossInfoPanel:RecycleWeakBreakFX()
    if self.ptcBossWeakBreakingEnter then
        UIBattlingTools.RecyclePoolObj(self.ptcBossWeakBreakingEnter)
        self.ptcBossWeakBreakingEnter = nil
    end
    if self.ptcBossWeakBreakingDuration then
        UIBattlingTools.RecyclePoolObj(self.ptcBossWeakBreakingDuration)
        self.ptcBossWeakBreakingDuration = nil
    end
end

function UIBattlingBossInfoPanel:RecycleWeakBrokenFX()
    if self.ptcBossWeakBrokenEnter then
        UIBattlingTools.RecyclePoolObj(self.ptcBossWeakBrokenEnter)
        self.ptcBossWeakBrokenEnter = nil
    end
    if self.ptcBossWeakBrokenDuration then
        UIBattlingTools.RecyclePoolObj(self.ptcBossWeakBrokenDuration)
        self.ptcBossWeakBrokenDuration = nil
    end
end

---CleanBossWeakFX
---清理 boss解体 相关特效
function UIBattlingBossInfoPanel:CleanBossWeakFX()
    self:RecycleWeakBreakFX()
    self:RecycleWeakBrokenFX()
end

---BossInfoMsgType
--- BossMsg 管理
---@param msg table
function UIBattlingBossInfoPanel:BossInfoMsgType(msg)
    if msg.type == 1 then
        --- 创建Boss信息
        self:SetBossInfoPanel(msg.data)
    elseif msg.type == 2 then
        --- Boss血量
        --- {roleId = 1, per = 0.5, maxPer = 0.5}
        if msg.data then
            if isSet(msg.data, "maxPer") then
                xTry(function()
                    self.hpMaxNow = msg.data.maxPer
                    -- self.Img_HpBlock.fillAmount = (1 - self.hpMaxNow)
                    self.LT_hpBlockSlider:SetProgress(1 - self.hpMaxNow)
                end)
            end
            local hpPre = msg.data.per or 1
            hpPre = hpPre * self.hpMaxNow
            self:SetBossHp(hpPre)
        end
    elseif msg.type == 3 then
        --- BossSP
        self:SetBossSp(msg.data)
    elseif msg.type == 4 then
        --- BossWeakness
        self:SetBossWeaknessFX(msg.data)
        local bossWeakStatus =  msg.data.state
        if bossWeakStatus == PanelShowState.Weakness then
            self:InitWeakBrokenHitEvent()
        else
            self:RemoveWeakBrokenHitEvent()
        end
    elseif msg.type == 5 then
        xTry(function()
            self:SetBossShield(msg.data)
        end)
    end
end

function UIBattlingBossInfoPanel:SetCGUseCardShow(bool)
    if not IsNull(self.cgSkillRoot) then
        self.cgSkillRoot.alpha = bool and 1 or 0
    end
end

--- 切换boss头像背后的底板（普通，狂暴，虚弱三种状态颜色不一样）
---@param state number
function UIBattlingBossInfoPanel:SwitchBossHeadBg(state)
    if not isNull(self.BossHeadBg) then
        if state == 1 then
            -- sleep状态
            self.BossHeadBg.Status = 3
        elseif state == 2 then
            -- 狂暴状态
            self.BossHeadBg.Status = 1
        elseif state == 3 then
            -- 虚弱状态
            self.BossHeadBg.Status = 2
        elseif state == 4 then
            -- out状态
            self.BossHeadBg.Status = 3
        end
    end
end

--- 设置下一条血的颜色
---@param colorCode any
function UIBattlingBossInfoPanel:SetNextHPSliderColor(colorCode)
    if isNull(self.Img_NextHPSlider) then
        self.Img_NextHPSlider = self.RT_HpSliderMultilayer:GetComponent(typeof(CS.UnityEngine.UI.Image))
    end
    if isNull(self.Img_NextHPSlider) then
        return
    end
    self.Img_NextHPSlider.color = XLuaUtils.HexToColor(colorCode)
end

